    private static final class GameTimeContext
    extends AbstractMaidContext {
        private GameTimeContext() {
            super("game_time", "Time");
        }

        @Override
        public String getValue(EntityMaid maid) {
            long time = maid.f_19853_.m_46468_();
            long hours = (time / 1000L + 6L) % 24L;
            long minutes = time % 1000L / 16L;
            return "%02d:%02d".formatted(hours, minutes);
        }
    }

    private static final class WeatherContext
    extends AbstractMaidContext {
        private WeatherContext() {
            super("weather", "Weather");
        }

        @Override
        public String getValue(EntityMaid maid) {
