    private static final class ArmorItemsContext
    extends AbstractMaidContext {
        private ArmorItemsContext() {
            super("armor_items", "Equipped armor");
        }

        @Override
        public String getValue(EntityMaid maid) {
            ArrayList names = Lists.newArrayList();
            maid.m_6168_().forEach(stack -> {
                if (!stack.m_41619_()) {
                    String itemName = stack.m_41611_().getString();
                    int count = stack.m_41613_();
                    names.add("%sx%s".formatted(itemName, count));
                }
            });
            if (names.isEmpty()) {
                return "Empty";
            }
            return StringUtils.join((Iterable)names, (String)", ");
        }
    }
}
